// Binary assets travel as base64 and are decoded once, on first request.
function decode(entry) {
  if (!entry.bytes) {
    const binary = atob(entry.base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    entry.bytes = bytes;
  }
  return entry.bytes;
}

function asset(entry) {
  const headers = {
    ...SECURITY,
    "Content-Type": entry.type,
    "Cache-Control": entry.cache || STATIC_CACHE,
  };
  if (entry.html) {
    headers["Cache-Control"] += ", no-transform";
    Object.assign(headers, HTML_HEADERS);
  }
  return new Response(entry.base64 === undefined ? entry.body : decode(entry), {
    status: 200,
    headers,
  });
}

export default {
  // The execution context must travel with the request: the API defers push
  // delivery through context.waitUntil, and without it a threshold-crossing PUT
  // would stay open until every notification had been sent.
  async fetch(request, env, context) {
    if (request.method === "GET") {
      const path = new URL(request.url).pathname;
      const key = path === "/" ? "/index.html" : path;
      if (Object.prototype.hasOwnProperty.call(ASSETS, key)) {
        return asset(ASSETS[key]);
      }
    }
    // /u/{id}, CORS preflight, and every 404/405 stay with the API logic above.
    return api.fetch(request, env, context);
  },
};
